var o=`1366-bunuelos-colombianos`;var n=`world-1366`;var s=`CO`;var t=`south-america`;var a=8;var r=44;var g={en:`Buñuelos Colombianos`,ua:`Колумбійські буньюелос`};var u={en:`Buñuelos Colombianos is a dish from Colombia featuring cornstarch, tapioca starch, queso fresco, chicken egg. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Колумбійські буньюелос, страва кухні країни Колумбія з такими основними складниками: кукурудзяний крохмаль, тапіоковий крохмаль, кесо фреско, куряче яйце. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:13,i:[[`cornstarch`,250,`g`],[`tapioca-starch`,150,`g`],[`queso-fresco`,320,`g`],[`chicken-egg`,2,`pcs`],[`white-granulated-sugar`,55,`g`],[`baking-powder`,10,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 16 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 16 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:16,i:[[`canola-oil`,850,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`powdered-sugar`,45,`g`]]}];var d={slug:o,id:n,country:`CO`,region:t,servings:8,minutes:44,title:g,text:u,steps:l};export{s as country,d as default,n as id,r as minutes,t as region,a as servings,o as slug,l as steps,u as text,g as title};